<span class="line"><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;">    &quot;build&quot;</span><span style="--shiki-light:#0184BC;--shiki-dark:#ABB2BF;">:</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> &quot;node build.js&quot;</span></span>
